// Intended function: choose one of twenty weather regimes from stable climate inputs and translate it into bounded simulation multipliers.
#include "world/WeatherSystem.hpp"
#include "core/Determinism.hpp"
#include <algorithm>
namespace elysium{WeatherState nextWeather(std::uint64_t p,std::uint64_t c,std::uint64_t t,float h,float temp,float a){auto s=mix64(p^mix64(c)^mix64(t/1200));float r=float((s>>40)&0xFFFFFF)/float(0xFFFFFF);WeatherKind k=WeatherKind::Clear;if(a>.8f&&r<.35f)k=WeatherKind::RiftAurora;else if(temp<-.5f)k=r<.45f?WeatherKind::Blizzard:WeatherKind::Snow;else if(temp>.7f&&h<.3f)k=r<.35f?WeatherKind::Haboob:(r<.7f?WeatherKind::HeatWave:WeatherKind::Dust);else if(h>.75f)k=r<.18f?WeatherKind::Thunderstorm:(r<.55f?WeatherKind::HeavyRain:WeatherKind::Rain);else{k=WeatherKind(std::uint8_t(r*20.f)%20);}WeatherState o{k,t,t+600+(s%1800),s,.25f+float((s>>20)&1023)/1364.f};return o;}WeatherEffects weatherEffects(const WeatherState&s){WeatherEffects e;float i=std::clamp(s.intensity,0.f,1.f);switch(s.kind){case WeatherKind::Fog:e.visibility=1-.75f*i;e.sensorNoise=.35f*i;break;case WeatherKind::HeavyRain:case WeatherKind::Thunderstorm:e.visibility=1-.45f*i;e.wind=.6f*i;e.precipitation=i;e.solarMultiplier=1-.7f*i;break;case WeatherKind::Blizzard:e.visibility=1-.8f*i;e.temperatureDelta=-30*i;e.wind=i;e.precipitation=i;e.solarMultiplier=.2f;break;case WeatherKind::HeatWave:e.temperatureDelta=35*i;e.solarMultiplier=1.1f;break;case WeatherKind::AcidRain:e.corrosion=i;e.precipitation=i;e.visibility=1-.35f*i;break;case WeatherKind::RadiationStorm:e.radiation=i;e.sensorNoise=.6f*i;break;case WeatherKind::ElectricalStorm:e.sensorNoise=i;e.wind=.7f*i;break;case WeatherKind::Dust:case WeatherKind::Haboob:case WeatherKind::AshFall:e.visibility=1-.7f*i;e.sensorNoise=.4f*i;e.solarMultiplier=1-.8f*i;break;case WeatherKind::ColdSnap:case WeatherKind::CryoMist:e.temperatureDelta=-20*i;e.visibility=1-.35f*i;break;default:break;}return e;}}
